INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (653,'comedy-1','Comedy #1','','Ian','An English-speaking magazine invites young people to take part in a writing competition. The participant must write a **comedy** — a humorous story consisting of 2 parts with a funny twist in the end.

The twist must be based on the following premise:

*An exchange student accidentally becomes famous at school for giving the best advice, although he does not understand half of what people are saying. One day, the headteacher asks him to solve a serious problem.*

In your article, you **must include three** of the following idioms:

-	once in a blue moon

-	the elephant in the room

-	a blessing in disguise

-	to spill the beans

-	to bite off more than one can chew

You decide to take part and submit your own story.

Your **comedy** must have:

-	a title

-	two parts

-	two cases of direct speech

-	one case of indirect speech

-	a humorous twist in the end

Your story may be written either in the first person or in the third person.

Write **200-250** words.','published',5,'2026-09-05T15:42:23.533Z','2026-09-05T18:23:47.876Z','2026-09-05T15:42:23.533Z','essay','[{"id":"writing-1788658850861","type":"writing","title":"","instructions":"Write your response to the task below.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Writing','[]','Story');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (654,'take-two-1','Take Two #1','','Ian','','published',5,'2026-09-05T15:53:48.547Z','2026-09-09T16:30:40.145Z','2026-09-05T15:53:48.547Z','essay','[{"caseSensitive":false,"revealAnswers":false,"completionText":"","completionMaterials":[],"ladderSide":"left","ladderStart":"","ladderEnd":"","readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":false,"id":"gap-fill-1788659317442","type":"gap-fill","title":"","instructions":"Complete each line by filling in the blanks with two words that match the clues. After completing each pair, remove one letter from each word to create a new word containing 6 or 7 letters. There is an example at the beginning.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":0,"prompt":"FLO**P** / WE**A**R – fail badly / _ _ _ _ your heart on your sleeve. – ...","answers":["flower"],"extraAnswers":[],"options":[],"example":true,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":1,"prompt":"_ _ _ _ / _ _ _ _ _ – Earth’s satellite / to guide the course of a vessel. – ...","answers":["monster"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":2,"prompt":"_ _ _ _ / _ _ _ _ _ – a headland / a mark or