,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":9,"prompt":"_ _ _ _ / _ _ _ _ _ – not limited or controlled / a bright, smooth surface. – ...","answers":["freshen"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":10,"prompt":"_ _ _ _ _ / _ _ _ _ – to move clumsily, bump into things / an ache. – ...","answers":["bargain"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":11,"prompt":"_ _ _ _ / _ _ _ _ _ – jelly (plural) / The Pine Tree State. – ...","answers":["jasmine"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','final','Use of English','[]','Vocabulary');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (655,'london-streets','London Streets','','Ian','','published',5,'2026-09-05T16:17:50.399Z','2026-09-06T17:08:23.291Z','2026-09-05T16:17:50.399Z','essay','[{"matchingMode":"interactive","matchingShowLabels":true,"matchingReuse":false,"id":"column-match-1788660844753","type":"column-match","title":"Questions 1–5","instructions":"For items 1–5, match each item in the left column with a description. There are extra descriptions that you will not need. The first example (0) is done for you.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":0,"prompt":"Westminster","answers":["I"],"extraAnswers":[],"options":[],"example":true,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":1,"prompt":"Covent Garden","answers":["E"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"Oxford Street","answers":["G"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"Fleet Street","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"Soho","answers":["L"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"Mayfair","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":"For much of the twentieth century, this central London street was strongly associated with Britain’s newspaper industry. Major national newspapers had their offices and printing presses here, making the area a symbol of British journalism. Although most newspapers later moved elsewhere, the street’s name is still commonly used as a general expression for the British press and newspaper profession."},{"label":"B","text":"This affluent district developed a reputation for expensive homes, luxury hotels, private clubs and exclusive shops. Its position between several famous shopping streets and large royal parks has helped make it one of London’s most prestigious addresses. Historically, wealthy families settled here, and today the area remains closely associated with embassies, high-end businesses, art galleries and some of the capital’s most expensive property."},{"label":"C","text":"This street became internationally famous partly because of a fictional character rather than a real historical resident. In the late nineteenth century, a writer chose an address here as the London home of a highly observant detective and his doctor companion. The street itself lies in an area that later became strongly associated with medicine, museums, transport links and prosperous residential development."},{"label":"D","text":"This district east of the historic City became home to many immigrant communities over several centuries. In the nineteenth century, it was known for poverty, overcrowded housing and social problems, while later generations brought new businesses and cultural influences to the area. It is also strongly connected with one of Britain’s most notorious unsolved series of crimes, which took place in the surrounding streets in 1888."},{"label":"E","text":"Once known for workshops, warehouses and a major fruit-and-vegetable market, this central area changed dramatically during the twentieth century. The former market buildings now contain restaurants and shops, while nearby streets are strongly associated with theatre and performance. Street entertainers frequently perform in its pedestrian spaces, helping make the district popular with visitors even though its original commercial function has largely disappeared."},{"label":"F","text":"This broad London street connects areas associated with government, ceremonial occasions and royal history. Its appearance differs from that of an ordinary commercial street because major public buildings and monuments dominate the surroundings. Processions and nationally significant events have often passed along or near it. Its location gives it a symbolic role linking the institutions of the state with spaces connected to the British monarchy."},{"label":"G","text":"This street runs through one of London’s principal commercial areas and became famous for large department stores. During the nineteenth century, improvements in transport and the growth of consumer culture transformed it into a major shopping destination. Although international brands now dominate parts of it, its name remains closely associated with London retail, especially the tradition of large stores attracting shoppers from Britain and abroad."},{"label":"H","text":"This area developed around docks that were once essential to London’s international trade. Warehouses stored goods arriving from different parts of the world, but changes in shipping caused the docks to decline during the twentieth century. Large-scale redevelopment later introduced offices, apartment buildings and modern transport connections. The contrast between its industrial past and its present role as a major business district is especially striking."},{"label":"I","text":"This district lies at the centre of British political life and contains institutions connected with Parliament, government and the monarchy. Its importance developed over many centuries rather than through modern commercial growth. The area includes major ceremonial spaces and buildings used for national events, political debate and administration, which explains why its name is sometimes used more broadly to refer to Britain’s political establishment."},{"label":"J","text":"This road has long been associated with fashionable clothing and British popular culture. It became especially influential during the 1960s, when boutiques, designers and youth-oriented businesses helped make the surrounding area a centre of “Swinging London.” Its reputation later changed as larger international retailers arrived, but the street continues to be remembered for its role in fashion, music and changing attitudes among young people."},{"label":"K","text":"Historically, this district developed as an important centre for London’s Jewish community and later became particularly associated with immigrants from Bangladesh. Restaurants, clothing businesses, markets and religious institutions reflect these different stages of migration. Today it is also known for street art, nightlife and creative industries, creating a mixture of older working-class traditions, immigrant cultures and more recent forms of urban redevelopment."},{"label":"L","text":"This central London district has repeatedly changed character. It has been associated with immigrant communities, restaurants, music clubs, publishing, nightlife and the entertainment industry. During the twentieth century, it became particularly important to London’s jazz and popular-music scenes. Its narrow streets and dense mixture of businesses distinguish it from nearby areas known for government buildings, formal institutions or luxury residential squares."},{"label":"M","text":"This residential district became particularly fashionable during the nineteenth century and is characterised by terraces, garden squares and large houses. In the twentieth century, parts of it attracted artists and writers, while other sections became associated with wealthy international residents. Its architecture and relative quiet contrast with the busy commercial districts nearby, despite its location within a short distance of central London’s major attractions."}]}]}]',NULL,'','regional','Use of English','[]','Country studies');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (656,'maslow','Maslow''s hierarchy of needs','','Ian','','published',5,'2026-09-05T17:30:27.826Z','2026-09-06T17:03:42.258Z','2026-09-05T17:30:27.826Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-tf-1788665287107","type":"listening-tf","title":"Questions 1–10","instructions":"For items 1–10, listen to the recording and decide whether each statement is TRUE (A) or FALSE (B). You will hear the text TWICE.","audioKey":"379c5c3a-dd8e-41df-9810-f8c943ea7d49.mp3","audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"The first published version of Maslow’s Pyramid of Needs was divided into 5 sections of different colours, each surrounded by academic text.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"The pyramid was created by a Russian psychologist of Jewish origin, thirty-five years old at the time.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"Maslow was interested in studying contemporary America and the way to make modern Americans’ lives more meaningful.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"Maslow claimed that people consciously replaced religion with psychology.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"Abraham Maslow had no personal interest in creating his legendary pyramid.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"Maslow’s use of the word ‘spiritual’ in the development of the model implied some mystic forces being involved.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":7,"prompt":"According to Maslow’s classification, the needs for bodily security and protection from attack were considered our basic physiological needs.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":8,"prompt":"The last need outlined by Maslow was the need for belongingness, which became a truly famous term.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":9,"prompt":"Maslow defined the urge for self-actualization as becoming our true selves.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":10,"prompt":"The younger generation tends to be particularly perplexed with questions of human existence and human desires.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','True / False');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (657,'multiple-choice-1','Multiple choice #1','','Ian','','published',5,'2026-09-05T17:54:10.203Z','2026-09-05T17:54:10.203Z','2026-09-05T17:54:10.203Z','essay','[{"id":"listening-choice-1788666767400","type":"listening-choice","title":"Questions 11–15","instructions":"For items 11–15, listen to the recording and choose the correct answer (A, B or C). You will hear the text only ONCE.","audioKey":"18c26cd2-791e-4cb8-952e-c24028e68c95.mp3","audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":11,"prompt":"When the group meet at the airport they will have","answers":["B"],"extraAnswers":[],"options":[{"label":"A","text":"breakfast."},{"label":"B","text":"coffee."},{"label":"C","text":"lunch."}],"example":false,"row":0,"col":0,"direction":"across"},{"number":12,"prompt":"The group will be met at Munich Airport by","answers":["C"],"extraAnswers":[],"options":[{"label":"A","text":"an employee at the National Theatre."},{"label":"B","text":"a theatre manager."},{"label":"C","text":"a tour operator."}],"example":false,"row":0,"col":0,"direction":"across"},{"number":13,"prompt":"How much will they pay per night for a double room at the hotel?","answers":["A"],"extraAnswers":[],"options":[{"label":"A","text":"110 euros"},{"label":"B","text":"120 euros"},{"label":"C","text":"150 euros"}],"example":false,"row":0,"col":0,"direction":"across"},{"number":14,"prompt":"What type of restaurant will they go to on Tuesday evening?","answers":["B"],"extraAnswers":[],"options":[{"label":"A","text":"an Italian restaurant"},{"label":"B","text":"a Lebanese restaurant"},{"label":"C","text":"a typical restaurant of the region"}],"example":false,"row":0,"col":0,"direction":"across"},{"number":15,"prompt":"Who will they meet on Wednesday afternoon?","answers":["C"],"extraAnswers":[],"options":[{"label":"A","text":"an actor"},{"label":"B","text":"a playwright"},{"label":"C","text":"a theatre director"}],"example":false,"row":0,"col":0,"direction":"across"}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]',NULL);
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (658,'us-cities','US Cities','','Ian','','published',5,'2026-09-05T18:05:05.026Z','2026-09-06T17:08:12.300Z','2026-09-05T18:05:05.026Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"gap-fill-1788667365446","type":"gap-fill","title":"","instructions":"For items 1–6, complete each sentence by choosing the place name from the box. Write the correct letter of the name in the space for each sentence. There are some extra names that you will not need.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"Since its establishment as a French colony in 1718, **_______** has witnessed some fascinating episodes in history, changing hands multiple times through Spanish conquests and the Louisiana Purchase.","answers":["New Orleans"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"Established by the Spanish in 1565 and commonly referred to as the “Old City”, _______ is the oldest permanently occupied European settlement in the US, predating the landing of the pilgrims on Plymouth Rock and the founding of Jamestown, Virginia by several decades.","answers":["St. Augustine"],"extraAnswers":[],"options":[],"example":false,"row":2,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"_______ is the place where American independence was declared, and today you’ll find its streets still soaked with history. You can visit the Liberty Bell, Independence Hall or the Museum of the American Revolution.","answers":["Philadelphia"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"While many think of the Big Apple as the ultimate modern city, _______ is full of history. Ellis Island is the natural place to start as it is the precise place where millions began their quest for the American Dream. Walk down Wall Street, stop at the Statue of Liberty and scale the Empire State Building—arguably the nation''s most iconic skyscraper.","answers":["New York"],"extraAnswers":[],"options":[],"example":false,"row":6,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"_______ is more associated with cutting-edge technology and forward-thinking these days, but it still makes for a great place to look back. Make a pilgrimage to Mission Dolores—the oldest building in town—to see where the city was founded before taking a tour of the Cable Car Museum.","answers":["San Francisco"],"extraAnswers":[],"options":[],"example":false,"row":8,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"While the Great Fire of 1871 wiped out much of _______, history buffs will still find plenty of impressive sights. The gorgeous Old Water Tower survived the blaze and offers a glimpse into the past while a stroll along the Magnificent Mile presents many 20th century architectural gems like the Wrigley Building and Tribune Tower.","answers":["Chicago"],"extraAnswers":[],"options":[],"example":false,"row":10,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[{"id":"464980bd-ef2a-40c7-8d69-8461ce3ed51f","key":"","name":"Table","kind":"table","caption":"","position":"after-instructions","afterParagraph":0,"cells":[["A","Atlanta","E","New Orleans","I","San Francisco"],["B","Chicago","F","New York","J","Santa Fe"],["C","Detroit","G","Philadelphia","K","St. Augustine"],["D","Montgomery","H","San Antonio","L","Washington, DC"]],"headerRow":false,"tableMode":"interactive","showLetters":false,"insertValue":"word","reuseWords":false}]','Country studies');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (659,'competition-entry-1','Competition entry #1','','Ian','Write your **competition entry**.

The entry must contain:

- an introduction

- an explanation of the importance of music in your own life

- a description of how music influences today’s world

- discussion of what the world would be like without music

- a conclusion.

Write **200-250** words. Provide a **title** for your entry.','published',5,'2026-09-05T18:14:35.536Z','2026-09-05T18:21:34.951Z','2026-09-05T18:14:35.536Z','essay','[{"id":"writing-1788668027544","type":"writing","title":"","instructions":"You see the following announcement in a music magazine:","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Writing','[{"id":"e5b18210-37cd-4265-b586-ed163d4fa2a7","key":"08a0294f-a140-4ef9-bd51-48949b96df18.png","name":"Screenshot 2026-09-05 at 9.12.47 PM.png","kind":"image","caption":"","position":"after-instructions","afterParagraph":0}]','Competition entry');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (660,'article-1','Article #1','','Ian','Write your **article**.

In your article, you must include the following idioms:

- be caught between a rock and a hard place

- weigh the pros and cons

- bite the bullet

Write **200-250** words. Provide a **title** for your article.','published',5,'2026-09-05T18:19:23.202Z','2026-09-05T21:15:36.047Z','2026-09-05T18:19:23.202Z','essay','[{"id":"writing-1788668290825","type":"writing","title":"","instructions":"You have seen the following announcement in an international magazine:","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Writing','[{"id":"10b148f7-90b0-40eb-8965-03aceef01163","key":"","name":"Announcement","kind":"announcement","caption":"","position":"after-instructions","afterParagraph":0,"heading":"DILEMMAS","text":"Have you faced a dilemma recently? In other words, you found yourself in a difficult situation in which you had to choose between two or more courses of action? If so, we would like you to write us an article telling us:\n\n- what the dilemma was exactly & what the possible courses of action were\n- what you decided to do and why\n- what the outcome of your decision was\n\n**We will publish the best articles**"}]','Article');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (661,'proposal-1','Proposal #1','','Ian','Traffic problems have become a serious issue in your city, affecting daily life for many residents. The city authorities have invited members of the public to submit proposals suggesting practical solutions to improve traffic flow. You decide to respond by writing a **proposal** in which you recommend **several measures** the city administration could introduce. In your proposal, explain what actions should be taken, what impact these actions are likely to have on congestion, and how the necessary funding could be obtained.

The **proposal** must contain:

-	an introduction

-	a description of the suggested measures

-	an explanation of the expected effects on traffic condition

-	an explanation of how the measures could be financed

-	a conclusion

Write **200-250** words. Provide the **title** and the **subheadings**.','published',5,'2026-09-05T18:23:38.315Z','2026-09-05T18:23:38.315Z','2026-09-05T18:23:38.315Z','essay','[{"id":"writing-1788668590991","type":"writing","title":"","instructions":"Write your response to the task below.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Writing','[]','Proposal');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (662,'boston-tea-party','Boston Tea Party','','Ian','','published',5,'2026-09-05T18:36:54.206Z','2026-09-06T17:03:51.506Z','2026-09-05T18:36:54.206Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-tf-1788669329102","type":"listening-tf","title":"Questions 1–10","instructions":"For items 1–10, listen to the recording and decide whether each statement is TRUE (A) or FALSE (B). You will hear the text TWICE.","audioKey":"589e9fc9-79f8-4abf-858a-e7b307826f84.mp3","audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"Illegal transportation and trade underlay the Boston Tea Party.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"Annual tea consumption in the 18th-century in England is estimated to have been more than 200 cups per person.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"Tax evasion was common among the American colonists.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"In preparation for the Seven Years’ War, Britain decided to impose heavier taxes on its colonies.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"Several British soldiers were killed by Americans in the Boston Massacre.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"The Tea Act of 1773 stipulated that Britain intended to sell its tea in America through special merchants sent from London.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":7,"prompt":"On December 16, 1773, Bostonians gathered at the Old South Meeting House before going to the harbour.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":8,"prompt":"Sam Adams shouted that the meeting was useless for the country and called on people to stop protesting.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":9,"prompt":"The British government decided to close the port of Boston permanently.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":10,"prompt":"The First Continental Congress lasted less than a year.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','True / False');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (663,'global-inventors','Global Inventors','','Ian','All too often, inventors from the U.S. and European countries are incorrectly credited for creating the modern world. Popular accounts of technological history frequently present innovation as a largely Western achievement, focusing on a limited group of well-known figures. In fact, various nations around the world are truly responsible for many of the innovations that have shaped our lives today. This imbalance in recognition can partly be explained by the way history has traditionally been written and taught.

	To give one example, European armies are credited with developing the modern firearm in the 19th and early 20th centuries. It is true that the European guns were hand-held combustion weapons that could quickly fire a bullet, just like today’s handguns. These weapons proved highly influential in later military conflicts. However, it is also true that 600 years earlier, Chinese armies had already been using firearms called “hand cannons,” which had many of the essential features of the European weapons that came later. These early devices demonstrate that firearm technology did not originate in Europe alone.

	Then there is the case of the airplane. The world remembers American inventors Wilbur and Orville Wright for creating modern flight, with their development of a steerable, motorized flying machine in 1903. Their work is often highlighted because it marked a turning point in transportation history. Yet Brazilian aviator Alberto Santos-Dumont had made the world’s first true steerable motorized flying machine in 1899. It is further worth noting that the Wright Brothers’ first flights in 1903 and 1904 lasted less than five minutes, while Santos-Dumont’s 1899 flight lasted nearly a half hour.

	But perhaps the most popular modern invention that historians wrongly thank Europe for is the camera, a device nearly everyone owns and uses today. Photography has become essential in fields ranging from journalism to science. Most history books name 19th-century French photographer Louis Daguerre as the inventor of the camera. In fact, the true inventor of the camera was an Iraqi scientist born nearly 1,000 years before Daguerre. Ibn al-Haytham developed pinhole camera technology, the basis for modern photography, in the early 11th century. Although his device could not produce permanent images, it provided the foundation for later photographic developments.

	This is yet another prominent example of Western inventors dominating our historical awareness, so that we fail to notice how much the rest of the world has contributed to modern life. A broader perspective allows us to better understand how innovation has always been a global process.','published',5,'2026-09-05T18:41:51.876Z','2026-09-06T17:06:15.109Z','2026-09-05T18:41:51.876Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-integrated-1788669495835","type":"listening-integrated","title":"Questions 16–25","instructions":"Read the text below, then listen to a talk on the same topic. You will notice that some ideas coincide and some differ in them. Answer questions 16-25 by choosing A if the idea is expressed in both materials, B if it can be found only in the reading text, C if it can be found only in the audio-recording, and D if neither of the materials expresses the idea.","audioKey":"28a11b3d-128a-43dd-9d76-fe26f80b0026.mp3","audioInstructions":"Now listen to another text on the same topic and then do the tasks (questions 16-25), comparing the text above and the interview. You will hear the text TWICE.","readingMinutes":15,"questions":[{"number":16,"prompt":"Innovations from outside Europe and the U.S. are often overlooked in history.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":17,"prompt":"Chinese hand cannons were essentially the same as modern European firearms.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":18,"prompt":"Ibn al-Haytham invented a device that could take photographs.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":19,"prompt":"Santos-Dumont built a motorized flying machine that could be steered.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":20,"prompt":"Santos-Dumont’s aircraft was safe and efficient to operate.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":21,"prompt":"The Wright brothers invented the first truly practical airplane.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":22,"prompt":"Modern cameras depend on earlier pinhole camera discoveries.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":23,"prompt":"Early inventions were often impractical despite being innovative.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":24,"prompt":"Early Chinese firearms shared some features with later European guns.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":25,"prompt":"European firearms were designed so that a single person could operate them.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','Integrated L&R');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (664,'valentine-day','Valentine’s Day','','Ian','','published',5,'2026-09-05T18:47:56.701Z','2026-09-06T17:04:15.291Z','2026-09-05T18:47:56.701Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-tf-1788669961915","type":"listening-tf","title":"Questions 1–10","instructions":"For items 1–10, listen to the recording and decide whether each statement is TRUE (A) or FALSE (B). You will hear the text TWICE.","audioKey":"e2427e15-3acf-4ce3-ac55-bf06b75d5694.mp3","audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"Saint Valentine of Rome was the only historical figure linked to Valentine’s Day.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"Valentine’s reputation as the patron saint of love is clearer than the historical facts about his life.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"Emperor Claudius believed unmarried soldiers were better fighters.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"Valentine’s medical work was less dangerous than his secret marriages.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"Valentine treated victims of war as well as widespread diseases.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"Valentine was imprisoned before the emperor learned about his weddings.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":7,"prompt":"The jailer doubted Christianity until his daughter regained her sight.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":8,"prompt":"Valentine was spared execution because of the miracle he performed.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":9,"prompt":"The expression “from your Valentine” comes from a prison farewell.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":10,"prompt":"Cheap postal services helped turn Valentine’s story into a global tradition.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','True / False');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (665,'global-warming','Global Warming','','Ian','Concern about the phenomenon known as global warming has been growing in recent years. Earth’s temperature is rising, largely as a result of human activity. Since the Industrial Revolution, humans have added significantly to the greenhouse gases in the Earth’s atmosphere through increases in activities such as cutting down forests and burning fossil fuels like coal and oil. Greenhouse gases hold heat in the atmosphere and to a certain extent, their presence is natural. An artificial increase in the amount of these gases, however, leads to a rise in temperatures on Earth.

	In the middle of the twentieth century, scientists discovered that Earth was getting warmer. Then they discovered that carbon dioxide levels in the atmosphere were increasing. They realized that there was a relationship between rising temperatures and rising levels of carbon dioxide. Most of this carbon dioxide comes from emissions from industrial activity and gasoline-powered motor vehicles.

	Earth’s average temperature increased almost 1.5°F during the twentieth century. Scientists predict that during the twenty-first century, temperatures will continue to increase. What changes could this bring about on our planet? We have already begun to see changes in weather patterns, snow and ice cover, and sea level.

	Changes in weather patterns may lead to increased flooding and drought worldwide, as well as more frequent extreme weather conditions such as powerful hurricanes. Rising global temperatures may also result in increasing water scarcity and in the extinction of numerous plant and animal species. But not just the weather will be affected. Changes in climate can lead to economic losses, particularly in the agricultural and transportation sectors. One report predicts a possible 1% drop in gross domestic product and a 20% decrease in per capita consumption worldwide.','published',5,'2026-09-05T18:51:03.698Z','2026-09-06T17:05:16.658Z','2026-09-05T18:51:03.698Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-integrated-1788670168283","type":"listening-integrated","title":"Questions 16–25","instructions":"Read the text below, then listen to a talk on the same topic. You will notice that some ideas coincide and some differ in them. Answer questions 16-25 by choosing A if the idea is expressed in both materials, B if it can be found only in the reading text, C if it can be found only in the audio-recording, and D if neither of the materials expresses the idea.","audioKey":"d7f238aa-b6c0-44ca-93c7-9776a653cb7e.mp3","audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":7,"questions":[{"number":16,"prompt":"Scientists identified the link between carbon dioxide and warming in the twentieth century.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":17,"prompt":"Snow cover in the northeastern United States has become less consistent from year to year.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":18,"prompt":"Climate change has already led to observable environmental changes.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":19,"prompt":"Reduced snowfall has directly lowered the profits of ski resorts in the northeastern United States.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":20,"prompt":"Measured data show that temperatures have increased over time.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":21,"prompt":"Warmer autumns have negatively affected foliage-related tourism.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":22,"prompt":"Winter has shown the strongest warming trend in the northeastern United States.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":23,"prompt":"Human activity has significantly contributed to rising global temperatures.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":24,"prompt":"Industries dependent on seasonal tourism in the Northeast are threatened by long-term warming.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":25,"prompt":"Global warming is expected to cause worldwide economic damage.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','Integrated L&R');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (666,'us-lakes','US Lakes','','Ian','','published',5,'2026-09-05T18:55:35.627Z','2026-09-06T17:07:57.617Z','2026-09-05T18:55:35.627Z','essay','[{"matchingMode":"interactive","matchingShowLabels":true,"matchingReuse":false,"id":"column-match-1788670362197","type":"column-match","title":"Questions 1–6","instructions":"For items 1–6, match each item in the left column with a description. There are extra descriptions that you will not need.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"Lake Superior","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"Caddo Lake","answers":["F"],"extraAnswers":[],"options":[],"example":false,"row":2,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"Lake Tahoe","answers":["E"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"Mirror Lake","answers":["H"],"extraAnswers":[],"options":[],"example":false,"row":6,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"Lake Michigan","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":8,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"Hamilton Pool","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":"It is one of the five Great Lakes of North America and the only one, whose surface lies in the US only and is not shared with Canada. The lake also contains numerous islands, notably the Beaver Island archipelago and the North and South Manitou Islands located between the Upper and Lower peninsulas."},{"label":"B","text":"It is one of the most unusual as well as beautiful lakes in the world. The lake is part of Travis County Park. It formed thousands of years ago after a calciferous dome broke off the ground and fell, opening and forming a fascinating pool. It is considered to be ground and underground lake simultaneously. A 15m waterfall contributes to the fascinating natural beauty."},{"label":"C","text":"The deepest lake in America is also one of the deepest in the world, and reaches depth of 594 m. The water is crystal clear and the lake is surrounded with stunning cliffs and is embedded in the mountains. It also boasts two beautiful islands."},{"label":"D","text":"It is the largest of the five Great Lakes of North America and one of the world’s largest bodies of fresh water. Bounded on the east and north by Ontario (Canada), on the west by Minnesota (U.S.), and on the south by Wisconsin and Michigan (U.S.), it discharges into Lake Huron at its eastern end via the St. Marys River. It is 563 km long (east to west), and its greatest width is 258 km from north to south."},{"label":"E","text":"This clear, cobalt blue lake tucked into the snowy Sierra Nevada Mountain range, welcomes athletes, adventurers and casual travelers to its easygoing and pine-scented atmosphere. A long sought-after vacation destination, the lake keeps everyone’s interests piqued and their vacations active throughout the year. It is the nation’s second deepest lake, and the area previously served as a transcontinental route for first the railroad and later highways."},{"label":"F","text":"One of the most unique and enigmatic lakes in the world. It is famous for flooding the trunks of the cypress trees. The waters of the lake are rich with various species of marine life. Boating through the like provides one of the most unusual and unforgettable experiences."},{"label":"G","text":"Known as the \"Queen of the American Lakes,\" with its 109 miles of shoreline and 300+ islands, the lake has been a vacation paradise for almost two centuries. Families come to experience the many lakeside activities, including beaches and fishing, or to get out on the lake for a ride on a classic paddleboat or in a pontoon boat or canoe."},{"label":"H","text":"This small yet perfectly formed lake can be found in none other than Yosemite National Park which will probably give you some indication as to the beauty of the surrounding environment. Pine trees, snow-capped mountains and glacial sharp definition all go towards making the lake live up to all of your wildest wilderness expectations and anyone interested in natural photography need look no further for some sensational scenery to capture, print and hang on the wall."}]}]}]',NULL,'','regional','Use of English','[]','Country studies');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (667,'william-shakespeare','William Shakespeare','','Ian','**William Shakespeare**

William Shakespeare (1564–1616) is considered to be one of the greatest writers of English literature. But did he really write Romeo and Juliet, Hamlet, Macbeth, and the other plays attributed to him? Scholars have long questioned the authenticity of the claim that these works were written by William Shakespeare of Stratford-on-Avon, England. There are a number of reasons why. 

	In the first place, William Shakespeare was a man of humble origins. He was not a wealthy aristocrat or nobleman. Rather, he was the son of a tradesman, and there is no record that he ever went to school. Yet many of his plays deal with the lives of nobility and show an understanding of politics, science, literature, and foreign languages that only an aristocrat or an educated person would have had. 

	In addition, very few concrete facts about Shakespeare’s life are known. There are very few written records containing information about him. This seems unusual for someone who became as well known as Shakespeare did. Some scholars take this as evidence that records were destroyed to hide the true identity of the author of the plays attributed to Shakespeare. 

	Several contemporary writers have been suggested as the possible true author of Shakespeare’s works. One of the more popular theories is that they were written by Sir Francis Bacon, a prominent scholar, diplomat, and writer. This claim is based in part on perceived similarities between some of Bacon’s writing and certain phrases found in the plays attributed to Shakespeare. Other well-known writers, including playwright Christopher Marlowe and Edward de Vere, 17th Earl of Oxford, have also been put forth as possible authors of the plays.','published',5,'2026-09-05T19:01:52.293Z','2026-09-06T17:05:45.540Z','2026-09-05T19:01:52.293Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-integrated-1788670831612","type":"listening-integrated","title":"Questions 16–25","instructions":"Read the text below, then listen to a talk on the same topic. You will notice that some ideas coincide and some differ in them. Answer questions 16-25 by choosing A if the idea is expressed in both materials, B if it can be found only in the reading text, C if it can be found only in the audio-recording, and D if neither of the materials expresses the idea.","audioKey":"d3d9b7b2-719a-4305-b772-9a3a1e784281.mp3","audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":7,"questions":[{"number":16,"prompt":"Some people doubt that Shakespeare was the true author of the plays.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":17,"prompt":"Alternate author theories collapse for lack of solid ground.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":18,"prompt":"A whole cast of other writers has been dragged into the authorship debate.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":19,"prompt":"The lack of records about Shakespeare’s life proves that someone else wrote the plays.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":20,"prompt":"Some believe records were erased to mask the real author.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":21,"prompt":"Shakespeare’s missing records can be chalked up to his low place on the social ladder.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":22,"prompt":"There is no proof that Shakespeare ever received formal schooling.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":23,"prompt":"Critics argue that limited education alone disproves Shakespeare’s authorship.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":24,"prompt":"Francis Bacon is often named as a possible author of Shakespeare’s plays.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":25,"prompt":"When Bacon and Shakespeare are put side by side, their prose speaks in different voices.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','Integrated L&R');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (668,'stonehenge','Stonehenge','','Ian','**Stonehenge**

	Stonehenge, located on the Salisbury Plain in England, is a circular arrangement of bluestones and sarsen stones. Each bluestone weighs several tons, and each sarsen stone weighs ten tons or more. The question is, what was the original purpose of this monument?

	Many theories have been put forward—the most popular being that ancient astronomers may have used Stonehenge as a solar calendar; however, excavations by researchers from the Stonehenge Riverside Project support a newer hypothesis. Evidence of burials and cremations dating back to 3000 B.C.E. led researchers involved in the Riverside Project to conclude that the real purpose of Stonehenge was to serve as a burial site. More than 50,000 cremated bone fragments of 63 individuals were excavated and studied by the team, including about equal numbers of men and women, as well as an infant.

	In addition to cremated remains, chalk dust in several holes suggested that fifty-six bluestones once stood in the circular arrangement. According to the lead researcher, Professor Mike Parker Pearson, bluestones have been closely associated with burials from similar time periods, and their presence serves as further support for the burial ground hypothesis.

	Finally, although few artifacts have been unearthed at Stonehenge, the head of a stone mace, an object similar to a scepter, supports the assumption that important persons were selected for burial at the site. A small bowl, burned on one side, may have held incense, further suggesting that the dead could have been religious and political leaders and their immediate families. Most prehistoric burials in England involved leaving the dead in the wild for animals to clean them or throwing the bodies into rivers, another indication that the Stonehenge burial site was reserved for leaders. Clearly, a possession like the stone mace would have belonged to someone of high rank and status among those who occupied the site and could have been buried with the body.','published',5,'2026-09-05T19:08:15.886Z','2026-09-06T17:05:06.637Z','2026-09-05T19:08:15.886Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-integrated-1788671232259","type":"listening-integrated","title":"Questions 16–25","instructions":"Read the text below, then listen to a talk on the same topic. You will notice that some ideas coincide and some differ in them. Answer questions 16-25 by choosing A if the idea is expressed in both materials, B if it can be found only in the reading text, C if it can be found only in the audio-recording, and D if neither of the materials expresses the idea.","audioKey":"98c081ff-f3e4-4197-b4fd-5852e5a42569.mp3","audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":7,"questions":[{"number":16,"prompt":"The “new” burial evidence is basically old news.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":17,"prompt":"Cremations there involved both adults and even a very young child.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":18,"prompt":"Experts have pinned down the exact year Stonehenge was completed.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":19,"prompt":"Human remains were found at Stonehenge, showing burials took place there.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":20,"prompt":"Some people think bluestones were chosen because they could ring out when hit.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":21,"prompt":"Bluestones were exclusively used for burial rituals.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":22,"prompt":"Back then, bodies were often dumped in wilder ways elsewhere in England.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":23,"prompt":"Bluestones are linked to burials in one way or another.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":24,"prompt":"Some visitors may have taken away tiny bluestone chips as keepsakes.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":25,"prompt":"Stonehenge burials may have been for big shots, not ordinary people.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','Integrated L&R');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (669,'puns-1','Puns #1','','Ian','','published',5,'2026-09-05T19:12:09.039Z','2026-09-05T19:13:28.215Z','2026-09-05T19:12:09.039Z','essay','[{"id":"gap-fill-1788671392624","type":"gap-fill","title":"Questions 1–7","instructions":"For items 1–7, fill in the gaps to complete each pun. The number of letters in each word is specified. Each pun is based on an idiom – think creatively, and let your humour do the work.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"I’ve encountered quite a few birthday thieves in my life, but this one (5 letters + 3 letters \n+ 4 letters).","answers":["takes the cake"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across"},{"number":2,"prompt":"I often say “música” to my Spanish-speaking friends.\n\tIt’s (5 letters) to their (4 letters).","answers":["music ears"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across"},{"number":3,"prompt":"I wasn’t originally going to get a brain transplant, but then I (7 letters + 2 letters + 4 \nletters).","answers":["changed my mind"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across"},{"number":4,"prompt":"My friend’s bakery burnt down last night… now his business is (5 letters).","answers":["toast"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across"},{"number":5,"prompt":"I should’ve known inventing a boomerang with teeth would come back to (4 letters + 2 letters).","answers":["bite me"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across"},{"number":6,"prompt":"I’m afraid for the calendar… its days are (8 letters).","answers":["numbered"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across"},{"number":7,"prompt":"My grandfather invented the cold-air balloon, but it never got (3 letters + 3 letters + 6 letters).","answers":["off the ground"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across"}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[]',NULL);
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (670,'article-2','Article #2','','Ian','Write your **article**.

In your article, you must include the following idioms:

- soak up the atmosphere

- a hidden gem

- a stone’s throw away

Write **200-250** words. Provide a **title** for you article.','published',5,'2026-09-05T19:15:25.103Z','2026-09-05T21:53:28.537Z','2026-09-05T19:15:25.103Z','essay','[{"id":"writing-1788671656408","type":"writing","title":"","instructions":"You have seen the following announcement in an international magazine:","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Writing','[{"id":"9c7e1443-243a-433a-80aa-dbdb05d06364","key":"","name":"Announcement","kind":"announcement","caption":"","position":"after-instructions","afterParagraph":0,"heading":"VISIT MY CITY!","text":"Are you looking for your next unforgettable trip? Would you like to explore somewhere exciting, full of character, and packed with things to do? If so, we would like you to write us an article persuading tourists to visit your area. In your article, tell us:\n\n- what makes your area special (give a little background information)\n- what two local tourist attractions you would recommend and why\n- why visitors would enjoy spending time there\n\n**We will publish the best articles**"}]','Article');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (671,'pre-raphaelite-brotherhood','Pre-Raphaelite Brotherhood','','Ian','','published',5,'2026-09-05T19:19:01.331Z','2026-09-06T17:04:01.905Z','2026-09-05T19:19:01.331Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-tf-1788671890454","type":"listening-tf","title":"Questions 1–10","instructions":"For items 1–10, listen to the recording and decide whether each statement is TRUE (A) or FALSE (B). You will hear the text TWICE.","audioKey":"eb5122f8-36c3-4d86-b675-f1d9e4dae5e1.mp3","audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"The group tried to break the mold of British painting.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"Their emergence went hand in hand with political upheaval across Europe.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"The brotherhood started out with seven members.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"Despite the name, they had it in for Raphael himself.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"Literature was their bread and butter, unlike religious themes.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"Millais shocked the public by portraying sacred figures as ordinary workers.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":7,"prompt":"The public was horrified because Millais rejected the idealised depiction of the Holy Family.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":8,"prompt":"They used bright traditional colours rather than modern industrial pigments.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":9,"prompt":"Ophelia leaves viewers up to their necks in natural detail.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":10,"prompt":"Tiny visual details reveal what the characters are doing.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','True / False');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (672,'ellis-island','Ellis Island','','Ian','**Ellis Island**

	In the late nineteenth and early twentieth centuries, millions of people immigrated to the United States in search of economic opportunity, political stability, and improved living conditions. For many of these newcomers, Ellis Island was the first place they encountered upon arrival. Located in New York Harbor, Ellis Island operated as the primary federal immigration station from 1892 to 1954 and played a crucial role in regulating the entry of immigrants into the country.

	During its sixty-two years of operation, more than twelve million immigrants arrived at Ellis Island, most of them traveling by ship under difficult conditions. Upon arrival, passengers were required to undergo medical examinations and legal inspections designed to identify illnesses or other factors that might prevent entry. While the majority of immigrants completed the process quickly and were admitted, others were detained for further questioning or medical treatment. In some cases, individuals were denied entry altogether and were forced to return to their countries of origin, often resulting in painful family separations.

	For most immigrants, Ellis Island represented hope and the promise of a better future. Many believed that the United States offered opportunities for employment, education, and social mobility that were unavailable in their home countries. Because of this, the island became known as the “Island of Hope.” However, for those who were rejected or detained for long periods, Ellis Island became the “Island of Tears,” symbolizing loss, uncertainty, and disappointment.

	The immigrants who passed through Ellis Island had a lasting impact on the development of the United States. They contributed labor to growing industries, helped build infrastructure, and added cultural diversity to American society. Historians estimate that approximately forty percent of Americans today can trace their ancestry to immigrants who entered the country through Ellis Island. Today, Ellis Island serves as a museum that welcomes over five million visitors annually, preserving the history of immigration and reminding visitors of the challenges and aspirations that shaped the nation.','published',5,'2026-09-05T19:21:45.406Z','2026-09-06T17:05:37.157Z','2026-09-05T19:21:45.406Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"listening-integrated-1788672030922","type":"listening-integrated","title":"Questions 16–25","instructions":"Read the text below, then listen to a talk on the same topic. You will notice that some ideas coincide and some differ in them. Answer questions 16-25 by choosing A if the idea is expressed in both materials, B if it can be found only in the reading text, C if it can be found only in the audio-recording, and D if neither of the materials expresses the idea.","audioKey":"9bb8c33a-e715-4522-ac5c-d399bae26d88.mp3","audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":16,"prompt":"Immigrants passing through Ellis Island helped build up U.S. industry and shape its culture.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":17,"prompt":"About half of today’s Americans can trace their roots back to Ellis Island.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":18,"prompt":"The museum may downplay the hardships immigrants faced after settling in.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":19,"prompt":"Substandard housing largely stemmed from immigrants crowding into big cities.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":20,"prompt":"For many, Ellis Island stood for both hope and heartbreak.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":21,"prompt":"Most immigrants were detained for long periods before being allowed to enter the country.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":22,"prompt":"Inspections sometimes tore families apart for good.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":23,"prompt":"Inspection decisions did not always hold up.","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":24,"prompt":"Ellis Island processed more immigrants than all other U.S. immigration stations combined.","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":25,"prompt":"“Island of Tears” captures the toll of long detentions and rejection.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Listening','[]','Integrated L&R');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (673,'pandora-box','Pandora''s box','','Ian','**PANDORA’S BOX**

Zeus, **(0) …** (very powerful, strong, or important) king of the gods, was furious. The humans had learned about fire, a sacred gift meant only for the **(1) …** (living forever and never able to die) gods of Mount Olympus. Zeus decided that Pandora, the first mortal woman, would punish the bold and ungrateful humans. Before she was sent to earth, the gods and **(2) …** (supernatural female beings with divine powers) gave Pandora special gifts. Aphrodite gave her beauty, Apollo gave her music, and Athena gave her wisdom. Zeus himself gave her curiosity. Then he handed Pandora a **(3) …** (strange or difficult to understand or explain) golden box and warned her never to open it.

On earth, Pandora kept the **(4) …** (proscribed) box on a high shelf. At first she obeyed Zeus, but her curiosity slowly grew stronger. Finally, she decided to take just one little peek. When Pandora lifted the lid, terrible things flew out into the world. Evil spirits and dark creatures spread **(5) …** (the feeling of wanting something that someone else has), greed, sickness, and **(6) …** (a feeling of great sadness or unhappiness) to every corner of the earth. Only one small being called hope remained behind in the box. Hope was left to comfort humans and help them **(7) …** (to suffer or experience something difficult or unpleasant with patience) the evils that had escaped.','published',5,'2026-09-05T19:26:41.118Z','2026-09-06T17:06:54.220Z','2026-09-05T19:26:41.118Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"crossword-1788672245354","type":"crossword","title":"Questions 1–7","instructions":"For items 1–7, solve the crossword using the definitions in brackets. Type your answers into the numbered blanks. The first example (0) is done for you.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and answer the questions, comparing the text and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":0,"prompt":"","answers":["mighty"],"extraAnswers":[],"options":[],"example":true,"row":3,"col":8,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":1,"prompt":"","answers":["immortal"],"extraAnswers":[],"options":[],"example":false,"row":1,"col":8,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[3]},{"number":2,"prompt":"","answers":["goddesses"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":5,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[8,2]},{"number":3,"prompt":"","answers":["mysterious"],"extraAnswers":[],"options":[],"example":false,"row":5,"col":3,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"","answers":["forbidden"],"extraAnswers":[],"options":[],"example":false,"row":1,"col":4,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[3,7]},{"number":5,"prompt":"","answers":["envy"],"extraAnswers":[],"options":[],"example":false,"row":7,"col":0,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"","answers":["sorrow"],"extraAnswers":[],"options":[],"example":false,"row":5,"col":12,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[5]},{"number":7,"prompt":"","answers":["endure"],"extraAnswers":[],"options":[],"example":false,"row":7,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[0]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[]','Crossword');
