INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (684,'flying-cars','Flying cars','','Ian','**FLYING CARS**

For decades, flying cars existed only in futuristic films and speculative fiction, symbolizing a sleek, high-tech future. Today, that vision is steadily (0) … (turning from an idea into something that actually exists) thanks to breakthroughs in electric (1) … (the force or system that moves a vehicle forward or upward), lightweight (2) … (made from two or more combined materials to create something stronger and lighter than the individual parts) materials, and autonomous navigation systems. Modern (3) … (the first designs of something from which other forms are copied or developed) — commonly known as eVTOLs (electric vertical take-off and landing vehicles) — are (4) … (carefully designed and constructed using scientific and technical knowledge) for short urban journeys rather than long-distance travel.

Despite rapid technological progress, significant hurdles remain. (5) … (government authorities or official bodies that create and enforce safety rules and standards) must develop reliable air-traffic management systems to prevent midair (6) … (overcrowding or blockage caused by too many vehicles in the same space), while manufacturers work to improve battery endurance, minimize noise, and (7) … (to ensure or make certain that something meets required standards or functions safely) rigorous safety standards. Nevertheless, successful test flights and pilot programs worldwide suggest that flying cars are moving beyond novelty status.','published',5,'2026-09-06T12:21:36.722Z','2026-09-06T13:43:36.681Z','2026-09-06T12:21:36.722Z','essay','[{"id":"crossword-1788733138106","type":"crossword","title":"Questions 1–7","instructions":"For items 1–7, solve the crossword using the definitions in brackets. Type your answers into the numbered blanks. The first example (0) is done for you.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":0,"prompt":"","answers":["materialising"],"extraAnswers":[],"options":[],"example":true,"row":0,"col":8,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":1,"prompt":"","answers":["propulsion"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":3,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[1,2,6]},{"number":2,"prompt":"","answers":["composite"],"extraAnswers":[],"options":[],"example":false,"row":3,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[0,7,8]},{"number":3,"prompt":"","answers":["prototypes"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":11,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[6]},{"number":4,"prompt":"","answers":["engineered"],"extraAnswers":[],"options":[],"example":false,"row":8,"col":5,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[2,1]},{"number":5,"prompt":"","answers":["Regulators"],"extraAnswers":[],"options":[],"example":false,"row":1,"col":3,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[0,4,1]},{"number":6,"prompt":"","answers":["congestion"],"extraAnswers":[],"options":[],"example":false,"row":3,"col":0,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[3,4,5]},{"number":7,"prompt":"","answers":["guarantee"],"extraAnswers":[],"options":[],"example":false,"row":11,"col":3,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[7,8]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[]','Crossword');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (685,'uk-people','UK People','','Ian','','published',5,'2026-09-06T12:27:29.319Z','2026-09-06T14:44:16.483Z','2026-09-06T12:27:29.319Z','essay','[{"matchingMode":"interactive","matchingShowLabels":true,"matchingReuse":false,"id":"column-match-1788733405357","type":"column-match","title":"Questions 1–10","instructions":"For items 1–10, match each item in the left column with a description. There are extra descriptions that you will not need.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":1,"prompt":"William Caxton","answers":["K"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":2,"prompt":"Alan Turing","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":2,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":3,"prompt":"Alfred Hitchcock","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":4,"prompt":"Audrey Hepburn","answers":["J"],"extraAnswers":[],"options":[],"example":false,"row":6,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"John Constable","answers":["L"],"extraAnswers":[],"options":[],"example":false,"row":8,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"Horatio Nelson","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":7,"prompt":"Elton John","answers":["I"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":8,"prompt":"Samuel Johnson","answers":["E"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":9,"prompt":"Frank Whittle","answers":["M"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":10,"prompt":"Juliana Berners","answers":["G"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":"He is a famous British movie director also known as the \"Master of Suspense\". Among his famous works are “Psycho”, “Vertigo” and “Rear Window”. He appeared in cameo roles in most of his films. He worked with a lot of famous artists and literary figures like John Steinbeck, Dorothy Parker and Raymond Chandler. Feeling constrained by the Hays Code, a set of guidelines for all the motion pictures of that time, He often battled with Hollywood censors. He received numerous awards for his work, including an honorary lifetime achievement Oscar."},{"label":"B","text":"This person (1874—1922) was an Anglo-Irish Antarctic explorer who attempted to reach the South Pole. In 1901, he was chosen to go on the Antarctic expedition led by British naval officer Robert Falcon Scott on the ship ''Discovery''. His fourth expedition aimed to circumnavigate the Antarctic continent but on 5 January 1922, he died of a heart attack off South Georgia."},{"label":"C","text":"He was a British flag officer in the Royal Navy. In 1783 he returned to England after the end of the American Revolution. In 1797 he distinguished himself while in command of HMS Captain at the Battle of Cape St Vincent. Spectacular success at the Battle of Trafalgar raised him to the rank of Britain''s national heroes."},{"label":"D","text":"He was an English logician, mathematician and computer scientist. He is generally known for his work in artificial intelligence and computer science. He is widely considered to be the father of theoretical computer science and artificial intelligence. During World War II, Turing worked at Bletchley Park and was involved in breaking the German Enigma Machine codes. His experiment tried to devise an intelligence standard for technology. It''s a test of a machine''s ability to exhibit intelligent behaviour equivalent to that of a human."},{"label":"E","text":"He was an English critic and lexicographer. He is the author of *A Dictionary of the English Language*. *A Dictionary of the English Language* was published in two volumes in 1755. It was the largest dictionary in the history of the English language at the time. It took him 9 years to write the dictionary. Although he is mostly famous for his dictionary, he was also a poet and spent years creating a collection of the works of Shakespeare. His life also made him the subject of the first modern biography written by James Boswell."},{"label":"F","text":"She was an English social reformer, statistician and the founder of modern nursing.  She came to prominence while serving as a manager of nurses trained by her during the Crimean War, where she organised the tending to wounded soldiers. In 1860, she laid the foundation of professional nursing with the establishment of her nursing school at St Thomas'' Hospital in London. She was a prodigious and versatile writer. Much of her writing, including her extensive work on medical studies, religion and mysticism, has only been published posthumously."},{"label":"G","text":"She was an Englishwoman of letters and the purported author of A Treatyse of Fysshynge wyth an Angle (1496), the earliest known volume on sport fishing. Her work predates Englishman Izaak Walton’s The Compleat Angler (1653), the best-known example of early angling literature, by approximately 150 years."},{"label":"H","text":"She was a schoolteacher before she married her husband Derek in 1962. She was a self-taught designer. After divorcing Derek, She moved in with McLaren. She and McLaren pursued a career in fashion. She is largely responsible for bringing modern punk and new wave fashions into the mainstream."},{"label":"I","text":"He was born in 1947, in England. He excelled in music from a young age, and released his first self-titled American album in 1970, making him a huge international star. He also found success on Broadway, composing the score for Billy Elliot (2008), which went on to win 10 Tony Awards. He was inducted into the Rock and Roll Hall of Fame in 1994 and was knighted in 1998. As one of the top acts of the 1970s, He became equally famous for his live shows. He is one of the biggest music icons of the 20th century. Some of his most famous hits include \"Crocodile Rock,\" \"Philadelphia Freedom\" and \"Candle in the Wind.\""},{"label":"J","text":"She was a British actress and humanitarian. Recognised as both a film and fashion icon, she was ranked by the American Film Institute as the third-greatest female screen legend from the Golden Age of Hollywood, and was inducted into the International Best Dressed List Hall of Fame. Her breakthrough came with the film \"Roman Holiday,\" for which she made history by winning an Oscar, a Golden Globe, and a BAFTA for a single role. She had a philanthropic side and was engaged in many humanitarian works were recognized by many organizations even posthumously."},{"label":"K","text":"He was an English merchant, diplomat, and writer. He is thought to be the first person to introduce a printing press into England, in 1476, and as a printer was the first English retailer of printed books. He set up a press at Westminster in 1476. The first book known to have been produced there was an edition of Chaucer’s *The Canterbury Tales*."},{"label":"L","text":"He was an English landscape painter in the Romantic tradition. He achieved international success in 1824 when “The Hay Wain” was shown at the Paris Salon, where he won a gold medal that was awarded by the king. In 1828, “Dedham Vale”, reprising a scene first painted in his youth, secured him a place in the Royal Academy of Arts. Nowadays he is remembered as one of the greatest 19th-century British landscape painters, who revolutionised the genre."},{"label":"M","text":"He graduated from Royal Air Force College to be commissioned as a Pilot Officer in 1928. When he first sent his engine design to Air Ministry in 1929, he was blamed for being impracticable. Left with no choice, he patented his idea himself. In 1937, the first turbo jet by him was made and called W. U. Thanks to his invention, he was made Fellow of the Royal Society and Honorary fellow of the Royal Aeronautical Society."}]}]}]',NULL,'','regional','Use of English','[]','Country studies');
