,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":5,"prompt":"We decided to go **_____** on dinner so no one felt awkward about the bill.","answers":["Dutch","Q"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"I tried reading that science journal, but it was all **_____** to me.","answers":["Greek","C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":7,"prompt":"The mystery unfolded like a **_____** doll, each clue revealing another hidden layer.","answers":["Russian","D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":8,"prompt":"Her excuse for missing the meeting had more holes than **_____** cheese, so nobody believed her.","answers":["Swiss","L"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":9,"prompt":"He slipped out of the party without saying goodbye, taking **_____** leave before anyone noticed.","answers":["French","V"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":10,"prompt":"Blue jeans are as **_____** as apple pie.","answers":["American","F"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":11,"prompt":"Why can''t they write these instructions in plain **_____**?","answers":["English","J"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":12,"prompt":"He gets his **_____** up every time someone insults his favorite football team.","answers":["Irish","K"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[{"id":"f3d722cb-0f29-4bac-98ef-406423a38cb7","key":"","name":"Table","kind":"table","caption":"","position":"after-instructions","afterParagraph":0,"cells":[["A","German","I","Japanese","Q","Dutch"],["B","Spanish","J","English","R","Turkish"],["C","Greek","K","Irish","S","Indian"],["D","Russian","L","Swiss","T","British"],["E","Welsh","M","Arabian","U","Swedish"],["F","American","N","Danish","V","French"],["G","Cuban","O","Mexican","W","Persian"],["H","Brazilian","P","Chinese","X","Moroccan"]],"headerRow":false,"tableMode":"interactive","showLetters":false,"labelPairs":true,"insertValue":"word","reuseWords":false}]','Vocabulary');
