ompt":"I was used to being sent to **_____** at school and not having any friends.","answers":["Coventry","O"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":6,"prompt":"The governor finally met his **_____** in the last election.","answers":["Waterloo","E"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":7,"prompt":"He’s crossed the **_____** with regard to the use of military force as an option.","answers":["Rubicon","A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":8,"prompt":"I wouldn’t take that job for all the tea in **_____**.","answers":["China","H"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":9,"prompt":"Environmentalists claimed governments were fiddling while **_____** burned.","answers":["Rome","K"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":10,"prompt":"Exporting pine to Scandinavia seems like carrying coals to **_____**.","answers":["Newcastle","C"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[{"id":"b95cab6e-8ab6-41a2-abed-3a9ee42c2c2f","key":"","name":"Table","kind":"table","caption":"","position":"after-instructions","afterParagraph":0,"cells":[["A","Rubicon","G","Troy","M","Siberia"],["B","Carthage","H","C