INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (688,'idioms-names-1','Idioms: Names #1','','Ian','','published',5,'2026-09-06T13:09:44.507Z','2026-09-09T18:08:04.212Z','2026-09-06T13:09:44.507Z','essay','[{"caseSensitive":false,"revealAnswers":false,"completionText":"","completionMaterials":[],"ladderSide":"left","ladderStart":"","ladderEnd":"","readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":false,"id":"gap-fill-1788735401563","type":"gap-fill","title":"Questions 1–27","instructions":"For items 1–27, complete each sentence with the most suitable name from the box. Use each name only once.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":1,"prompt":"We had barely turned up the music at the house party when the Old __________ showed up at the front door following a noise complaint from the neighbors.","answers":["Bill","G"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":2,"prompt":"The political ads airing during the football game were an obvious attempt to gain the votes of the __________ Six-Packs in the audience.","answers":["Joe","E"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":3,"prompt":"Having spent over sixty years together sharing every joy and hardship, the elderly couple down the lane were the quintessential __________ and Joan.","answers":["Darby","L"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":4,"prompt":"Avoid inviting Arthur to the weekend hiking trip unless you want a moaning __________ complaining about the incline and the weather the entire afternoon.","answers":["Minnie","R"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":5,"prompt":"For __________''s sake, please turn off the lights when you leave the room to save electricity!","answers":["Pete","H"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":6,"prompt":"He was happy as __________ when he found out he won the lottery.","answers":["Larry","M"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":7,"prompt":"For the love of __________, stop making that annoying clicking noise with your pen!","answers":["Mike","O"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":8,"prompt":"Don''t be such a silly __________ and put your shoes on the right feet!","answers":["Billy","S"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":9,"prompt":"What in the __________ Hill are you doing out here in the middle of a downpour without an umbrella?","answers":["Sam","Y"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":10,"prompt":"He faced a __________’s choice when the only options were to accept the offer on their terms or walk away with nothing.","answers":["Hobson","X"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":11,"prompt":"She was the Typhoid __________ of the office cold, infecting half the staff within a week.","answers":["Mary","P"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":12,"prompt":"When gasoline prices spike like this, it is __________ Q. Public who feels the pinch at the pump first.","answers":["John","V"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":13,"prompt":"She checked the tax records twice to make sure everything was according to __________.","answers":["Hoyle","K"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":14,"prompt":"Instead of simply flipping the light switch, he built a __________ contraption involving do