INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (691,'machu-picchu','Machu Picchu','','Ian','**MACHU PICCHU**

When the Empire of the Incas was at the (0) … (the point when something reaches its greatest level) of its power, around 1500, its towns and cities had excellent roads and efficient religious and (1) … (relating to the organisation and management of something) systems. In fact, it could be said to have been a civilisation which (2) … (was as good, powerful, successful, or impressive as something else) that of ancient Rome. It was not long, however, until (3) … (severe and widespread destruction or damage) was visited upon this great civilisation by Spanish invaders, greedy for gold.

A visit to Machu Picchu, a relatively small but spectacular Inca town, offers a glimpse of the vanished (4) … (great beauty that attracts admiration and attention) of the past. The centre of the town is dominated by a long stairway, the so-called Royal Mausoleum and an impressive semicircular temple. There is also an (5) … (containing a lot of careful detail or many detailed parts) series of stone water basins and a number of stone staircases.

The true wonder of Machu Picchu, however, lies not in its architectural planning, something at which the Incas excelled, but in the position of its site. It is (6) … (situated above or on the edge of something) on a steep mountain face with deep canyons on three sides and is therefore virtually (7) … (very difficult or impossible to travel to or reach). This probably explains why it seems to have been unknown to the Spaniards and why it has survived pretty much intact.','published',5,'2026-09-06T17:16:11.181Z','2026-09-06T17:16:34.148Z','2026-09-06T17:16:11.181Z','essay','[{"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"crossword-1788750742441","type":"crossword","title":"Questions 1–7","instructions":"For items 1–7, solve the crossword using the definitions in brackets. Type your answers into the numbered blanks. The first example (0) is done for you.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"number":0,"prompt":"","answers":["height"],"extraAnswers":[],"options":[],"example":true,"row":11,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"number":1,"prompt":"","answers":["administrative"],"extraAnswers":[],"options":[],"example":false,"row":5,"col":1,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[12,2,4,7]},{"number":2,"prompt":"","answers":["rivalled"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":12,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[4,3,0]},{"number":3,"prompt":"","answers":["devastation"],"extraAnswers":[],"options":[],"example":false,"row":1,"col":1,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[0,2,5,8]},{"number":4,"prompt":"","answers":["splendour"],"extraAnswers":[],"options":[],"example":false,"row":1,"col":5,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[7,8,4,1]},{"number":5,"prompt":"","answers":["elaborate"],"extraAnswers":[],"options":[],"example":false,"row":3,"col":1,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[5,6]},{"number":6,"prompt":"","answers":["perched"],"extraAnswers":[],"options":[],"example":false,"row":3,"col":9,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[1,4,6]},{"number":7,"prompt":"","answers":["inaccessible"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":14,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[9,10,1]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[]','Crossword');
