INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (705,'letter-words','Letter Words','','Ian','','published',5,'2026-09-07T19:11:12.243Z','2026-09-07T19:14:00.379Z','2026-09-07T19:11:12.243Z','essay','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"gap-fill-1788843340341","type":"gap-fill","title":"Questions 1–12","instructions":"For items 1–12, you are given a paraphrased section. You need to come up with a letter-derived word (or phrase/idiom) that fits the sentences grammatically and semantically. The letters, including some extra ones, are provided. The first example (0) is already done for you.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"additionalBlanks":[],"number":0,"prompt":"The programmer used a __concisely formatted literal__ to embed an expression. – [[0:1]]","answers":["F-string"],"extraAnswers":[],"options":[],"example":true,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":1,"prompt":"The doctor ordered a(n) __image__ to see if the fall had cracked any of my bones. – [[1:1]]","answers":["X-ray"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":2,"prompt":"If you want to make the team, you’ll have to bring your __best performance__ tonight. – [[2:1]]","answers":["A-game"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":3,"prompt":"Frustrated by the roadblock, the driver made a(n) __complete reversal__ in the middle of the street. – [[3:1]]","answers":["U-turn"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":4,"prompt":"It wasn’t until I had listened to the __reverse side__ of the record that I realised how versatile the band actually was. – [[4:1]]","answers":["B-side"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":5,"prompt":"I downloaded a(n) __digital version of a novel__ to read on my tablet during the trip. – [[5:1]]","answers":["E-book"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":6,"prompt":"She gently cleaned her baby’s ears with a(n) __small stick tipped with soft cotton__. – [[6:1]]","answers":["Q-tip"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":7,"prompt":"She preferred sweaters with a(n) __downward-pointing opening at the collar__. – [[7:1]]","answers":["V-neck"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":8,"prompt":"The __police unit with a highly trained German Shepherd__ was called to track the suspect. – [[8:1]]","answers":["K-9"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":9,"prompt":"He threw on a(n) __simple, short-sleeved top__ before heading out. – [[9:1]]","answers":["T-shirt"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":10,"prompt":"Doctors had to perform an emergency __operation in which the uterus is cut open__ when the baby’s heart rate dropped. – [[10:1]]","answers":["C-section"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":11,"prompt":"After four hectic weeks of electioneering, candidates are preparing themselves for __a day when something important will happen__ tomorrow. – [[11:1]]","answers":["D-day"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":12,"prompt":"I’m going to __take a quick nap__ to recharge before the conference. – [[12:1]]","answers":["catch some Z''s","cop some Z''s","get some Z''s"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','final','Use of English','[{"id":"b7f09820-098e-4d12-87c0-30d8ec1a9a99","key":"","name":"Word box","kind":"word-box","caption":"","position":"after-instructions","afterParagraph":0,"words":["B","T","V","X","A","K","E","U","C","D","Z","I","L","P","T","Q"]}]','Vocabulary');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (706,'a-radical-multimillionaire','A Radical Multimillionaire','Equal parts 1960s hippie and cosmetics tycoon, Body Shop founder Anita Roddick brings her chaotic, generous, and controversial brand of ethical activism to Ghana.','Ian','Anita Roddick squats in the back of a Jeep in Ghana’s blowtorch heat, bare-armed and wild-haired, dusty feet in worn sandals, sweat on her lined forehead. Her clothes are crumpled and her face is creased. She is the fourteenth-richest woman in Britain; she is the public face of the eco-friendly Body Shop, but she shrugs when anyone mentions her money. She doesn’t want to talk about her wealth, but about other people’s poverty. She doesn’t want to talk about cosmetics, but about the stories and traditions behind each pot of cocoa butter cream, or about beauty not being skin-deep, or the wisdom that comes with age, or the danger of microwave ovens and animal-tested hairsprays.

‘I am a child of the Sixties,’ she says. And so she is, with her flowing hair and peasant clothes, and her indefatigable love of all good causes; she’s an 26) … hippie, one of a dying breed.

I used to think that Anita Roddick was the female equivalent of Richard Branson, hiding her businesswoman’s heart under a cheesecloth smock, and cannily persuading intense teenage girls to buy lip gloss or little bottles of body creams in naff raffia baskets – cashing in on a fashion for ethical shopping by vigilante consumers who no longer want products that are tainted by child labour, oppressive regimes, or environmental damage.

A few years ago, Roddick came under a barrage of criticism. She won a bruising libel case against Channel Four, which had suggested that Body Shop cosmetics contained animal products, but then faced hostile media attention for the way that the company was set up, for the razzmatazz of its hype, and for advertising American Express in a manner that suggested a colonial complacency. Roddick insists that if you dig for dirt, you will always find some. Some of the mud seemed to stick. While we oddly continue to love Branson for his homey jerseys and his inarticulate pronouncements, the public seems irritated by Roddick’s garrulous, tireless, pushy and morally 27) … presence.

We are on our way to one of the villages near Tamale which supply the Body Shop with shea butter. Under the Fair Trade agreement, the Body Shop pays a ten per cent premium on top of the price, which goes into community projects.

We approach the village, and a throng of people is waiting. Anita unscrews the tops of 28) … creams, and their scent fills the baked air like incense in a church. She observes the shea-butter process. She praises the women – the wives and mothers and grandmothers – and listens to their worries: there’s been a drought for three years; there is no school. She promises money (out of her own trust fund) for the equipment. They cheer; they give her a goat, two guinea fowl and a great box of yams. Then everyone dances – and Anita dances the most enthusiastically of all, as the drum beats out its rhythms and the children tear up to her and giggle. I don’t know whether to be moved or appalled by this white woman coming to Africa and behaving like a queen, or by her 29) … combination of generosity and shamelessness.

In another village, further south and later in the trip, she promises that she will find a clinic (in Ghana, AIDS, malaria, yellow fever, fatal epidemics of measles and malnutrition are widespread). She is given another goat. She has a go at hacking cocoa pods off the trees, wielding the long pole tipped with a knife, stubborn and off-target. She questions the cooperative which runs the cocoa butter production about its bureaucracy. ‘I want to know what we’re doing here that’s different,’ she says. ‘I want to see results.’ A quarrel breaks out among the men, some of whom are drunk on palm gin. She stands up. ‘OK, OK, tell me.’ She looks around wildly. ‘Who is the best here at kissing?’

I feel embarrassed for her, by her – but maybe that is just my problem, for the quarrel peters out, and the women smile up at her adoringly: their fairy godmother, coming from another world, bearing gifts.

With Anita Roddick, there seems to be no gap between the thought and the 30) …, nor any sense of shame or dignity. This is her great strength and also her perpetual weakness: the way she plunges into things, with her symbolic passions, her spontaneous opinions. She is not chic, trendy or cool (nor, indeed, is The Body Shop). She clings to naivety and optimism. Of course, it can be disarming, and she knows and plays on this.

As we walk, she admits to guilt: she is a rich hippie, a radical multimillionaire. She is leaving most of her money to charities, not to her two daughters; she drives an old Golf and wears floppy, flowery skirts (‘I like to look like a peasant’) to business meetings in the City. She works very hard when she doesn’t need to.

Our last appointment in Ghana before flying home is at the British High Commission in Accra, where a reception is being held in Roddick’s honour. Drifting across the hum of cultured voices, I can hear Roddick laughing lustily. Who cares if she is a bit batty? Her hair is messy, her chin is up, and behind her glasses, her eyes are shrewd and bright and determined. There are many worse things to be than a wacky hippie with a large wallet and a large heart.','published',5,'2026-09-07T20:55:53.486Z','2026-09-08T17:54:18.960Z','2026-09-07T20:55:53.486Z','dispatch','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"id":"final-stage-1788849989975","type":"final-stage","title":"Questions 26–40","instructions":"Read the text and answer questions 26–40 below.","wordFormation":[{"number":26,"baseWord":"construct","answers":["unreconstructed"]},{"number":27,"baseWord":"insist","answers":["insistent"]},{"number":28,"baseWord":"moist","answers":["moisturising","moisturizing"]},{"number":29,"baseWord":"imitate","answers":["inimitable"]},{"number":30,"baseWord":"utter","answers":["utterance"]}],"trueFalse":[{"number":31,"prompt":"Anita Roddick appears largely indifferent to the status attached to her fortune.","answers":["A"]},{"number":32,"prompt":"The writer originally suspected that Roddick was exploiting ethical concerns primarily for commercial gain.","answers":["A"]},{"number":33,"prompt":"Richard Branson appears to have faced less public hostility than Anita Roddick.","answers":["A"]},{"number":34,"prompt":"Anita Roddick’s behaviour in Ghana drew disapproval from local officials.","answers":["C"]},{"number":35,"prompt":"Channel Four uncovered damaging information about Roddick.","answers":["B"]}],"multipleChoice":[{"number":36,"prompt":"The writer thinks that Anita Roddick","options":[{"label":"A","text":"pretends to be concerned about moral issues but is at heart a businesswoman."},{"label":"B","text":"is eccentric but well-intentioned on the whole."},{"label":"C","text":"is rather hypocritical."},{"label":"D","text":"is condescending to the people in the village."}],"answers":["B"]},{"number":37,"prompt":"The text states that The Body Shop sells products that","options":[{"label":"A","text":"contain some hidden animal products."},{"label":"B","text":"sometime contain mud."},{"label":"C","text":"are produced in a morally acceptable way."},{"label":"D","text":"appeal unfairly to young women."}],"answers":["C"]},{"number":38,"prompt":"According to the text, Anita Roddick","options":[{"label":"A","text":"agrees that in the past The Body Shop may have had some faults."},{"label":"B","text":"thinks that all the accusations against The Body Shop are completely unfounded."},{"label":"C","text":"thinks that American Express behave like colonialists."},{"label":"D","text":"has been over-criticised in the past."}],"answers":["A"]},{"number":39,"prompt":"In one of the villages, she visits Anita Roddick","options":[{"label":"A","text":"promises to build a new school."},{"label":"B","text":"goes to see the place where they make one of The Body Shop products."},{"label":"C","text":"distributes Body Shop products to the villagers."},{"label":"D","text":"promises the villagers money from The Body Shop to buy equipment."}],"answers":["B"]},{"number":40,"prompt":"When describing Anita, the writer of the article tends to be","options":[{"label":"A","text":"approving."},{"label":"B","text":"condemnatory."},{"label":"C","text":"discomfited."},{"label":"D","text":"critical yet wryly sympathetic."}],"answers":["D"]}]}]','84cc9b1f-ed77-4e22-829d-d13d64a3998c.jpg','','final','Reading','[]',NULL);
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (707,'article-4','Article #4','','Ian','You decide to take part and write the article in the name of the young man. 
 
The article should contain:

•	information about how nature disappeared, 

•	a description of the writer’s impressions of the artificial world, 

•	the idiom “the tip of the iceberg” used in context,

•	advice to the people living at the present time. 
 
Write 200-250 words. Don’t write a title. Underline the idiom.','published',5,'2026-09-07T21:12:21.176Z','2026-09-07T21:14:25.679Z','2026-09-07T21:12:21.176Z','essay','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"writing-1788851402417","type":"writing","title":"","instructions":"An English language magazine invites young people to participate in a writing competition. The participant must write a text based on the following premise:","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Writing','[{"id":"46828c3e-8425-437e-bdf7-f1ce73430904","key":"","name":"Announcement","kind":"announcement","caption":"","position":"after-instructions","afterParagraph":0,"heading":"","text":"*A young man gets into the future world 50 years from now where real nature no longer exists and has been fully replaced by artificial environments. Occasionally, he discovers descriptions and images of forests, animals, and oceans from the past which he has never experienced himself. He writes an article for the magazine describing what life is like without nature and gives advice to the people living at the present time.*"}]','Article');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (708,'register-1','Register #1','','Ian','**LETTER TO CLUB MEMBERS**

Dear Club Members,

We have an exciting few months ahead of us. The purpose of this letter is to [[0]] you on our plans for the [[1]]. First of all, there is a party to [[2]] new members. It costs £2 to come unless you are [[3]] by two new members, in which case you get in free. The price of the ticket includes entertainment and [[4]].

On the 31st, there is going to be talk by James Dixon about his journeys round the world. He is [[5]] to be very entertaining speaker and to have some interesting films of his journey. We are hoping very much that a large [[6]] of members will be able to attend this meeting. Mr Dixon was kind enough to [[7]] a meeting previously arranged in order to be with us.

Finally, can I remind you about our [[8]] visit to London. If there is enough interest we shall organise a visit to the capital towards the end of December. Please [[9]] us as soon as possible if you think you might be interested so that we can decide whether to go ahead with plans. We should also be grateful for [[10]] about specific places to visit or shows to see in the evening.

Looking forward to seeing you soon,

John Smith','published',5,'2026-09-08T16:19:45.304Z','2026-09-08T16:25:25.492Z','2026-09-08T16:24:45.150Z','essay','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"crossword-1788919850824","type":"crossword","title":"Questions 1–10","instructions":"For items 1–10, read the following notes made by a club secretary. Use the information in the notes to complete the numbered gaps in the letter to club members which follows. Use only one word for each gap. The words you need do not occur in the notes. The first example (0) is done for you.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"additionalBlanks":[],"number":0,"prompt":"","answers":["update"],"extraAnswers":[],"options":[],"example":true,"row":1,"col":10,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":1,"prompt":"","answers":["future"],"extraAnswers":[],"options":[],"example":false,"row":6,"col":9,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[3]},{"additionalBlanks":[],"number":2,"prompt":"","answers":["welcome"],"extraAnswers":[],"options":[],"example":false,"row":1,"col":7,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[0]},{"additionalBlanks":[],"number":3,"prompt":"","answers":["accompanied"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":6,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[1,2]},{"additionalBlanks":[],"number":4,"prompt":"","answers":["refreshments"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":15,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[2,5,6]},{"additionalBlanks":[],"number":5,"prompt":"","answers":["known"],"extraAnswers":[],"options":[],"example":false,"row":1,"col":4,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[3]},{"additionalBlanks":[],"number":6,"prompt":"","answers":["number"],"extraAnswers":[],"options":[],"example":false,"row":8,"col":11,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[3]},{"additionalBlanks":[],"number":7,"prompt":"","answers":["postpone"],"extraAnswers":[],"options":[],"example":false,"row":7,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":8,"prompt":"","answers":["proposed"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":0,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[3,7]},{"additionalBlanks":[],"number":9,"prompt":"","answers":["inform"],"extraAnswers":[],"options":[],"example":false,"row":3,"col":13,"direction":"down","imageKey":null,"imageAlt":"","givenLetters":[2]},{"additionalBlanks":[],"number":10,"prompt":"","answers":["suggestions"],"extraAnswers":[],"options":[],"example":false,"row":11,"col":5,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[0,1]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','final','Use of English','[{"id":"45542de3-ce9a-4c90-bc67-f7c7207a182f","key":"","name":"Announcement","kind":"announcement","caption":"","position":"after-instructions","afterParagraph":0,"heading":"NOTES","text":"Write to all club members to make them feel at home and to give them the latest details about all the activities coming up soon.\n\nMention:\n\n• Party on 18th - mainly to say hello to new members. If old members bring along 2 new members, they get in without paying for ticket. Otherwise £2 (this includes disco, snacks, coffee).\n\n• Talk by James Dixon ‘Sailing Round the World’. (M. told S. that he’s got some fantastic video film as well as loads of interesting anecdotes about his adventures.) Push for a good turnout, otherwise it looks bad - he’s put off a meeting with another group to speak to us.\n\n• Excursion to London (end Dec?) - to museum, restaurant and theatre but only if enough members are interested. People must let us know now if they think they might come along. Ask members to give us ideas on particular museums, restaurants and theatres they’d like to go to."}]','Vocabulary');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (709,'letter-1','Letter #1','','Ian','','published',5,'2026-09-08T16:31:32.071Z','2026-09-08T16:31:32.071Z','2026-09-08T16:31:32.071Z','essay','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"writing-1788921074451","type":"writing","title":"","instructions":"You are Mary Todd. It is the morning of 4 November, 1842, and you are making the last diary entry of your girlhood. You want to write it in the form of a letter to your future self.\n\nIn your letter, do not forget to mention the following things:\n\n•\twho your groom is\n\n•\tthe description of your dress\n\n•\tyour expectations of the matrimony\n\n•\twhether you have any doubts about the decision you have made.\n \nWrite 250-300 words.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','final','Writing','[]','Article');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (710,'newspapers','Newspapers','','Ian','','published',5,'2026-09-08T16:34:56.522Z','2026-09-08T16:34:56.522Z','2026-09-08T16:34:56.522Z','essay','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"interactive","matchingShowLabels":true,"matchingReuse":false,"id":"column-match-1788921138200","type":"column-match","title":"Questions 1–7","instructions":"For items 1–7, match each item in the left column with a description.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"additionalBlanks":[],"number":1,"prompt":"*The New York Times*","answers":["E"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":2,"prompt":"*USA Today*","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":2,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":3,"prompt":"*The Times*","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":4,"prompt":"*The Guardian*","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":6,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":5,"prompt":"*The Wall Street Journal*","answers":["F"],"extraAnswers":[],"options":[],"example":false,"row":8,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":6,"prompt":"*The Observer*","answers":["G"],"extraAnswers":[],"options":[],"example":false,"row":10,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":7,"prompt":"*The Daily Telegraph*","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":"It is a British daily (Monday to Saturday) national newspaper based in London. It began in 1785 under the title The Daily Universal Register founded by John Walter, adopting its current name on 1 January 1788. It and its sister paper (founded in 1821) are published by a subsidiary of News UK, in turn wholly owned by News Corp. It and its sister paper do not share editorial staff, were founded independently, and have only had common ownership since 1967."},{"label":"B","text":"It is a British daily newspaper. It was founded in 1821. Along with its sister papers *The Observer*, It is part of a Media Group, owned by the Scott Trust. The trust was created in 1936 to \"secure its financial and editorial independence in perpetuity and to safeguard its journalistic freedom and liberal values free from commercial or political interference\"."},{"label":"C","text":"It is an internationally distributed American daily middle-market newspaper that is the flagship publication of its owner, Gannett. Founded by Al Neuharth on September 15, 1982, it operates from Gannett''s corporate headquarters in McLean, Virginia. It is printed at 37 sites across the United States and at five additional sites internationally. Its dynamic design influenced the style of local, regional, and national newspapers worldwide through its use of concise reports, colorized images, informational graphics, and inclusion of popular culture stories, among other distinct features."},{"label":"D","text":"It is a national British daily broadsheet newspaper published in London and distributed across the United Kingdom and internationally. It was founded by Arthur B. Sleigh in 1855."},{"label":"E","text":"It is an American newspaper with worldwide influence and readership. Nicknamed the Gray Lady, it has long been regarded within the industry as a national \"newspaper of record\". The paper''s motto, \"All the News That''s Fit to Print\", appears in the upper left-hand corner of the front page. Founded in 1851, the paper has won 130 Pulitzer Prizes, more than any other newspaper. It is ranked 18th in the world by circulation and 3rd in the U.S."},{"label":"F","text":"It is an American business-focused, English-language international daily newspaper, with international editions also available in Chinese and Japanese. It, along with its Asian editions, is published six days a week by Dow Jones & Company, a division of News Corp. The newspaper is published in the broadsheet format and online. It has been printed continuously since its inception on July 8, 1889, by Charles Dow, Edward Jones, and Charles Bergstresser."},{"label":"G","text":"It is a British newspaper published on Sundays. In the same place on the political spectrum as its sister papers, it takes a social liberal or social democratic line on most issues. First published in 1791, it is the world''s oldest Sunday newspaper."}]}]}]',NULL,'','regional','Use of English','[]','Country studies');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (711,'holidays','Holidays','','Ian','','published',5,'2026-09-08T16:42:42.830Z','2026-09-08T16:42:42.830Z','2026-09-08T16:42:42.830Z','essay','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"interactive","matchingShowLabels":true,"matchingReuse":true,"id":"column-match-1788921417932","type":"column-match","title":"Questions 1–10","instructions":"For items 1–10, match each item in the left column with a description.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"additionalBlanks":[],"number":1,"prompt":"Eisteddfod","answers":["G"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":2,"prompt":"Hogmanay","answers":["H"],"extraAnswers":[],"options":[],"example":false,"row":2,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":3,"prompt":"Morris dance","answers":["C"],"extraAnswers":[],"options":[],"example":false,"row":4,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":4,"prompt":"Riverdance","answers":["F"],"extraAnswers":[],"options":[],"example":false,"row":6,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":5,"prompt":"Groundhog Day","answers":["E"],"extraAnswers":[],"options":[],"example":false,"row":8,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":6,"prompt":"Memorial Day","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":10,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":7,"prompt":"Cheese rolling","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":8,"prompt":"Thanksgiving","answers":["D"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":9,"prompt":"Labor Day","answers":["J"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":10,"prompt":"Halloween","answers":["I"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":"This unusual British tradition centers on a large wheel of Double Gloucester and a crowd of participants eager to sprint after it purely for the thrill. The spectacle unfolds on Cooper’s Hill in Gloucestershire, England. It is held every year on the Spring Bank Holiday Monday. There are four downhill races in total, three for men and one for women, with up to fourteen competitors taking part in each race."},{"label":"B","text":"This federal holiday in the United States is dedicated to commemorating members of the armed forces who lost their lives in service to the nation. In 1966, a congressional proclamation officially recognized Waterloo, New York, as the birthplace of the tradition, dating its origins back to 1866. Initially known as Decoration Day, the occasion focused on honoring Civil War soldiers. Following the First World War, its scope widened to include fallen service members from all American conflicts, and the name was eventually changed to reflect this broader tribute."},{"label":"C","text":"This traditional English folk performance is typically carried out in groups and accompanied by lively music. Although the earliest references from the 15th century place it within a courtly environment, by the late 16th century it had become associated with entertainments for ordinary people. By the end of the 19th century, however, the practice was rapidly fading and was remembered more as a local tradition than a regularly performed activity."},{"label":"D","text":"This national holiday traces its roots back to November 1621, when the Pilgrims gathered to share a meal and express gratitude to God for helping them endure the difficulties of their first year in the New World. Although similar observances had taken place earlier, it was in 1863 that President Abraham Lincoln officially proclaimed a nationwide day of thanks, helping to establish the annual tradition as a unifying American holiday."},{"label":"E","text":"This tradition, though widely recognized, is not a federal public holiday. According to popular belief, a groundhog emerges from its burrow on this day to forecast the coming weeks of winter or the arrival of spring. A key role in organizing the festivities in the town of Punxsutawney is played by the Punxsutawney Groundhog Club. In Pennsylvania, the groundhog replaced the badger, adapting an older European weather-prediction custom to local wildlife."},{"label":"F","text":"Also widely associated with Lord of the Dance, this theatrical production is built around traditional Irish music and step dancing. It first gained international attention as an interval act during the Eurovision Song Contest 1994, featuring Irish dance champions Jean Butler and Michael Flatley, with music composed by Bill Whelan. Since its debut, the production has toured more than 450 venues across the globe and has been seen by over 25 million people, securing its place as one of the most commercially successful dance shows ever staged."},{"label":"G","text":"This week-long cultural festival is known for its elaborate ceremonial pageantry and strong sense of tradition. It is held annually during the first week of August, with the location alternating between North and South Wales. Among its most distinctive rituals are the proclamation ceremony, the crowning of the bard, the chairing of the bard, and the awarding of the prose medal. At its heart, the festival is a celebration of the Welsh language and the enduring cultural heritage of Wales."},{"label":"H","text":"This is the name given in Scotland to New Year’s Eve festivities, whose roots are believed to stretch back to Viking winter celebrations. The festivities begin on the final night of the year and continue through New Year’s Day and into January 2, which is an official public holiday in Scotland. Traditional customs form a central part of the celebration. These include first-footing, the ceremonial swinging of fireballs, the ba’ game, the icy New Year’s swim known as the Loony Dook, and the communal singing of Auld Lang Syne at midnight."},{"label":"I","text":"It is a holiday celebrated each year on October 31. The tradition originated with the ancient Celtic festival of Samhain, when people would light bonfires and wear costumes to ward off ghosts. In the 8th century, Pope Gregory III designated November 1 as a time to honor all saints. Soon afterward, All Saints Day incorporated some of the traditions of Samhain. The evening before was known as All Hallows Eve. Over time, it evolved into a day of trick-or-treating, carving jack-o-lanterns, festive gatherings, wearing costumes, and eating treats."},{"label":"J","text":"It is a federal holiday in the United States and Canada celebrated on the first Monday of September to honor the social and economic achievements of workers. It was officially established and signed into law by President Grover Cleveland in 1894."}]}]}]',NULL,'','regional','Use of English','[]','Country studies');
INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (712,'hidden-inventors','Hidden Inventors','','Ian','','published',5,'2026-09-08T16:48:36.312Z','2026-09-08T16:49:47.955Z','2026-09-08T16:48:36.312Z','essay','[{"revealAnswers":false,"completionText":"","completionMaterials":[],"readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":true,"id":"gap-fill-1788921852329","type":"gap-fill","title":"Questions 1–10","instructions":"In each of the following sentences there is a surname of a British or an American inventor. For items 1–10, find them and write their first name in your answer sheet. If the inventor has a middle name, ignore it. The hidden name is not necessarily contained within one word. The first example (0) is done for you.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"additionalBlanks":[],"number":0,"prompt":"Faced with competition from the Far __East, man__y shipyards are struggling. – [[0]] (not *\"Eastman\"*)","answers":["George"],"extraAnswers":[],"options":[],"example":true,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":1,"prompt":"What you’re saying isn’t new. Tons of such cases have happened before. – ___","answers":["Isaac"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":2,"prompt":"‘I am Stephen, son of Peter,’ he said, trying to imitate the way the barbarian introduced himself. – ___","answers":["George"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":3,"prompt":"So far, a day of non-stop studying is my record. – ___","answers":["Michael"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":4,"prompt":"When I rang the bell, nobody answered. – ___","answers":["Alexander"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":5,"prompt":"There was an additional perk in it for Alice. – ___","answers":["William"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":6,"prompt":"Louis wanted a cup of tea, but was too shy to ask for it. – ___","answers":["Joseph"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":7,"prompt":"Ned is on holiday, so we’ll have to finish this project without his help. – ___","answers":["Thomas"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":8,"prompt":"The first tremor set off by Cuadrilla’s fracturing in England was strong enough to be felt. – ___","answers":["Samuel","Alan"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":9,"prompt":"‘Pull, man, pull!’ he cried, as the time was running out. – ___","answers":["Georg"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":10,"prompt":"I don’t think he’s being frank. Line 10 is always free; he couldn’t have possibly got stuck there. – ___","answers":["Benjamin","Rosalind"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','final','Use of English','[]','Country studies');
