anks":[],"number":4,"prompt":"Hardrada overcame the Saxon earls at the Battle of Fulford.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":5,"prompt":"When Harold confronted William’s forces, his troops had already endured a week of fighting.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":6,"prompt":"Historians do not fully agree on how Harold died.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":7,"prompt":"The Norman account presents an alternative version of Harold’s death.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":8,"prompt":"French became the language of court, over time replacing dominant Old English.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":9,"prompt":"The Domesday Book was introduced to facilitate tax reduction and stabilise Norman authority.","answers":["B"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"additionalBlanks":[],"number":10,"prompt":"William’s rule faced persistent rebellions after his victory.","answers":["A"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"labe