INSERT INTO "articles" ("id","slug","title","dek","author","body","status","read_time","created_at","updated_at","published_at","layout_style","tasks_json","header_image_key","header_image_alt","stage","topic","attachments_json","subgroup") VALUES (726,'idioms-names-2','Idioms: Names #2','','Ian','','published',5,'2026-09-09T17:37:40.220Z','2026-09-09T18:07:39.214Z','2026-09-09T17:37:40.220Z','essay','[{"caseSensitive":false,"revealAnswers":false,"completionText":"","completionMaterials":[],"ladderSide":"left","ladderStart":"","ladderEnd":"","readingPrompt":"Now you have {minutes} minutes to read the text.","showReadingTimer":true,"matchingMode":"dropdown","matchingShowLabels":true,"matchingReuse":false,"id":"gap-fill-1788974905163","type":"gap-fill","title":"Questions 1–16","instructions":"For items 1–16, complete each sentence with the most suitable name from the box. Use each name only once.","audioKey":null,"audioInstructions":"Now listen to a talk on the same topic and then do the tasks (questions 16-25), comparing the text above and the talk. You will hear the text TWICE.","readingMinutes":10,"questions":[{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":1,"prompt":"The toddler is a real __________: no matter how carefully we close the playpen, he always manages to escape.","answers":["Houdini"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":2,"prompt":"With his confident walk, cheeky grin, and love of showing off, Ryan sees himself as a bit of a __________ the Lad.","answers":["Jack"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":3,"prompt":"He is a real doubting __________ who won’t believe the project will finish on time until he sees the final report.","answers":["Thomas"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":4,"prompt":"Instead of discussing the real problem, the speaker created an Aunt __________ that was easy for everyone to attack.","answers":["Sally"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":5,"prompt":"The novel begins with a shy, self-described plain __________ who believes that nobody notices her.","answers":["Jane"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":6,"prompt":"After paying income tax, property tax, and several other charges, Martin complained that Uncle __________ wanted another share of his money.","answers":["Sam"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":7,"prompt":"Don’t be such a nervous __________; the plane is perfectly safe, and a little turbulence is normal.","answers":["Nellie"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":8,"prompt":"Detectives kept the unidentified hospital patient listed as __________ until her family could be located.","answers":["Jane Doe"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":9,"prompt":"__________ is traditionally depicted as a fat man wearing a waistcoat with the British flag on it.","answers":["John Bull"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":10,"prompt":"The police report referred to the unidentified male victim as __________ until his family recognized him.","answers":["John Doe"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":11,"prompt":"Not to be a __________, but the news headlines in the past few days have been grim.","answers":["Debbie Downer"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":12,"prompt":"Mia is a real Chatty __________; she can talk continuously for hours without taking a break.","answers":["Cathy"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":13,"prompt":"Nobody likes a smart __________ who interrupts the teacher just to show that he thinks he knows everything.","answers":["aleck"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":14,"prompt":"The new smartphone was designed for __________, not just for engineers and technology experts.","answers":["Joe Bloggs"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":15,"prompt":"A __________ contraption is an overly complicated and ridiculous machine that does a very simple job.","answers":["Heath Robinson"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]},{"givenFirst":"","givenSecond":"","joiner":"space","additionalBlanks":[],"number":16,"prompt":"The old sailor joked that he planned to live a long, dry life on land before ever visiting __________''s locker.","answers":["Davy Jones"],"extraAnswers":[],"options":[],"example":false,"row":0,"col":0,"direction":"across","imageKey":null,"imageAlt":"","givenLetters":[]}],"columns":[{"title":"Descriptions","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""},{"label":"E","text":""},{"label":"F","text":""},{"label":"G","text":""},{"label":"H","text":""}]}]}]',NULL,'','regional','Use of English','[{"id":"1952535b-9d39-422c-9c10-542db896ba69","key":"","name":"Table","kind":"table","caption":"","position":"after-instructions","afterParagraph":0,"cells":[["Sally","John Doe","Debbie Downer"],["Houdini","Jane Doe","Thomas"],["Sam","Jack","Heath Robinson"],["John Bull","Davy Jones","Jane"],["Nellie","Cathy","Joe Bloggs"]],"headerRow":false,"tableMode":"interactive","showLetters":false,"labelPairs":false,"insertValue":"word","reuseWords":false}]','Vocabulary');
