INSERT INTO "ege_tasks" ("id","subject","title","status","task_json","updated_at") VALUES ('354dc6ad-b6c2-4f38-9a96-c93e02ef8766','english','УЧ: Задание 1','published','{"id":"354dc6ad-b6c2-4f38-9a96-c93e02ef8766","title":"УЧ: Задание 1","subject":"english","template":"en-read-aloud","status":"published","instructions":"Prepare to read the text aloud. You have 1.5 minutes to prepare and 1.5 minutes to read it.","body":"In 2016, a small town in the Netherlands launched an unusual experiment to reduce food waste. Local shops began selling boxes of fruit and vegetables that did not look perfect but were still completely safe to eat. At first, many customers were unsure about the idea, but it soon caught on. Within 8 months, more than 40 local businesses had joined the project. The organisers discovered that people were willing to give it a try when the products were offered at lower prices. In some shops, food waste fell by almost 30%. The project also helped change the way people thought about appearance. A carrot with an unusual shape or an apple with a small mark was no longer seen as useless. By 2021, similar projects had appeared in several European cities. What started as a small local idea gradually made a difference, proving that simple changes in everyday habits can have a surprisingly large effect.\n","questions":[{"id":"4ce805b2-a684-42c4-bef3-db86c1ccd9ff","number":"1","prompt":"","baseWord":"","options":[],"answers":[],"audio":""}],"bank":[],"media":[],"caseSensitive":false,"reuse":false,"showAnswers":false,"minWords":0,"maxWords":0,"prepSeconds":90,"answerSeconds":90,"rubric":"","chooseOne":false}','2026-09-09T16:09:09.144Z');
INSERT INTO "ege_tasks" ("id","subject","title","status","task_json","updated_at") VALUES ('56c3b17d-b032-40d0-9bdd-2b9c38696b4a','english','УЧ: Задание 2','published','{"id":"56c3b17d-b032-40d0-9bdd-2b9c38696b4a","title":"УЧ: Задание 2","subject":"english","template":"en-ask","status":"published","instructions":"You are considering taking part in a weekend archaeological workshop and now you’d like to get more information. In 1.5 minutes you are to ask four direct questions to find out about the following:\n\n**ARCHAEOLOGY FOR A WEEKEND**","body":"1. **minimum age**\n\n2. **equipment provided**\n\n3. **accommodation options**\n\n4. **bad weather**\n\nYou have **20 seconds** to ask each question.","questions":[{"id":"8a48de5c-0651-4fe3-ac7a-4a253082ec35","number":"1","prompt":"","baseWord":"","options":[],"answers":[],"audio":""},{"id":"745975aa-b7ab-4d09-900c-aa78df8710af","number":"2","prompt":"","baseWord":"","options":[],"answers":[],"audio":""},{"id":"db88a8dd-7723-4bde-8e42-cfc45fba8f3e","number":"3","prompt":"","baseWord":"","options":[],"answers":[],"audio":""},{"id":"100e7ae5-8f56-46e8-be62-74d6ccf3e82a","number":"4","prompt":"","baseWord":"","options":[],"answers":[],"audio":""}],"bank":[],"media":[{"url":"/media/2143ab01-df25-4490-aef4-f65323bb1a20.png","kind":"image","name":"","position":"after"}],"caseSensitive":false,"reuse":false,"showAnswers":false,"minWords":0,"maxWords":0,"prepSeconds":90,"answerSeconds":20,"rubric":"","chooseOne":false}','2026-09-09T19:51:46.802Z');
